<?php
namespace Tests\Feature;
use App\Models\Module;use App\Models\Organization;use App\Models\SubscriptionOrder;use App\Models\User;use App\Services\PaystackService;use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class SubscriptionPaymentTest extends TestCase {use RefreshDatabase;
 public function test_verified_exact_payment_activates_only_purchased_module():void{$org=Organization::create(['name'=>'Paid Org','slug'=>'paid-org']);$user=User::factory()->create(['organization_id'=>$org->id]);$vts=Module::create(['code'=>'VTS','name'=>'VTS','available'=>true]);$vas=Module::create(['code'=>'VAS','name'=>'VAS','available'=>true]);$org->modules()->attach([$vts->id=>['enabled'=>false],$vas->id=>['enabled'=>false]]);$order=SubscriptionOrder::create(['organization_id'=>$org->id,'user_id'=>$user->id,'reference'=>'NMT-TEST','items'=>[['code'=>'VTS','cycle'=>'monthly','amount_kobo'=>250000]],'amount_kobo'=>250000,'currency'=>'NGN','status'=>'pending']);$this->assertTrue(app(PaystackService::class)->fulfill($order,['status'=>'success','amount'=>250000,'currency'=>'NGN','reference'=>'NMT-TEST','id'=>123]));$this->assertTrue($org->fresh()->hasModule('VTS'));$this->assertFalse($org->fresh()->hasModule('VAS'));$this->assertDatabaseHas('subscription_orders',['id'=>$order->id,'status'=>'paid']);}
 public function test_wrong_amount_never_activates_module():void{$org=Organization::create(['name'=>'Unpaid Org','slug'=>'unpaid-org']);$user=User::factory()->create(['organization_id'=>$org->id]);$module=Module::create(['code'=>'PBS','name'=>'PBS','available'=>true]);$org->modules()->attach($module->id,['enabled'=>false]);$order=SubscriptionOrder::create(['organization_id'=>$org->id,'user_id'=>$user->id,'reference'=>'NMT-BAD','items'=>[['code'=>'PBS','cycle'=>'monthly','amount_kobo'=>5000000]],'amount_kobo'=>5000000,'currency'=>'NGN','status'=>'pending']);$this->assertFalse(app(PaystackService::class)->fulfill($order,['status'=>'success','amount'=>100,'currency'=>'NGN','reference'=>'NMT-BAD']));$this->assertFalse($org->fresh()->hasModule('PBS'));}
}
